The following blocks form a $\mathrm{PD}(4;6,3)$ on the point set $\{0,\ldots,5\}$.
\[
\begin{array}{l}
\{0,1,2\} \\
\{0,3,4\} \\
\{1,3,5\} \\
\{2,4,5\}
\end{array}
\]

\label{th:horsley_pack_2}
Given positive integers $v$, $k$ and $\lambda$ such that $3 \leq k < v$, let $r$ and $d$ be the integers with $0 \leq d < k=1$ such that $\lambda(v-1)=r(k-1)+d$.  If $d \geq r-\lambda$, then
\[
\mathrm{PDN}_{\lambda}(k,v) \leq \left\lfloor \frac{rv(\alpha-\beta)-\alpha v}{k(\alpha-\beta)-1}\right\rfloor,
\]
where:
\begin{enumerate}
\item $\alpha=\frac{r-\lambda+1}{2d+2}$ and $\beta=0$ if $k(r+\lambda-1)>2d+2$;
\item $\alpha=\frac{r-\lambda}{2d+2}$ and $\beta=\frac{r-\lambda}{2(d+k)}$ if $(r-\lambda)k(k-1)>2(d+1)(d+k)$.
\end{enumerate}

\mbox{}
	For $t=2$ and $k \in \{3,4,5\}$,                                                               
	$\mathrm{DPDN}_\lambda(v,k) = B_{2\lambda}(v,k)$, except that
	\begin{itemize}
	\item $\mathrm{DPDN}(v,k) = U_2(v,k,2)-1$ for  $(v,k) \in \{(9,4), (13,5)\}$,
	\item $\mathrm{DPDN}(15,5) = U_2(15,5,2)-2$,
	\end{itemize}
	and except possibly when $k=5$ and $(v,\lambda) \in \{(19,1), (27,1), (43,3)\}$.

\label{add-delete points}
Suppose $v \geq k \geq t$ and $\lambda$ are positive integers, and let $v'$ and $k'$ be integers with $t \leq k' \leq k$ and $v \leq v'$.  Then:
\begin{enumerate}
\item $\mathrm{PDN}_{\lambda}(v,k,t) \leq \mathrm{PDN}_{\lambda}(v',k,t)$,
\item $\mathrm{PDN}_{\lambda}(v,k,t) \geq \mathrm{PDN}_{\lambda}(v,k',t)$,
\item $\mathrm{DPDN}_{\lambda}(v,k,t) \leq \mathrm{DPDN}_{\lambda}(v',k,t)$, and
\item $\mathrm{DPDN}_{\lambda}(v,k,t) \geq \mathrm{DPDN}_{\lambda}(v,k',t)$.
\end{enumerate}

Consider a $\mathrm{PD}_{\lambda}(d;v,k,t)$. For this packing design, by Lemma~\ref{General N-bound} we have
\begin{equation}\label{E:NBoundRestatement}
(t-1)\binom{d}{\lambda+1} \geq \sum_{i=1}^{n} N_i\binom{i}{\lambda+1}.
\end{equation}
Since $\sum_{i=1}^{d} N_i=v$, $\sum_{i=1}^{d} iN_i=dk$ and the function $\binom{i}{\lambda+1}$ is convex in $i$, we have that the right hand side of \eqref{E:NBoundRestatement} is minimized when $N_{q+1}=r$, $N_q=v-r$, and $N_i=0$ for all $i \in \{1,\ldots,n\} \setminus \{q,q+1\}$. Thus
\[
(t-1)\binom{d}{\lambda+1} \geq r\binom{q+1}{\lambda+1}+(v-r)\binom{q}{\lambda+1}=v\binom{q}{\lambda+1}+r\binom{q}{\lambda}
\]
where the equality follows by substituting $\binom{q+1}{\lambda+1}=\binom{q}{\lambda+1}+\binom{q}{\lambda}$ and simplifying.

Let $W_1,\ldots,W_4$, where $W_i=\{w_{i1},w_{i2}\}$, be the blocks of a $\mathrm{PD}(4;8,2)$ in which each point is in exactly one block. Applying the scheme described in the proof of Lemma~\ref{General Construction} to this packing design, we obtain a $\mathrm{PD}(4;14,5)$ whose blocks are
\[
\begin{array}{l}
\{w_{11}, w_{12}, u_{12}, u_{13}, u_{14} \} \\
\{w_{21}, w_{22}, u_{12}, u_{23}, u_{24} \} \\
\{w_{31}, w_{32}, u_{13}, u_{23}, u_{34} \} \\
\{w_{41}, w_{42}, u_{14}, u_{24}, u_{34} \}
\end{array}
\]
where we write $u_{xy}$ as a shorthand for $u_{\{x,y\},1}$.

\label{PDN}
Let $v \geq k \geq t \geq 2$, $\lambda \geq 1$ and $n \geq 1$ be integers.  We have that $\mathrm{PDN}_{\lambda}(v,k,t)=n$ if
\[nk-(t-1)\binom{n}{\lambda+1} \leq \lambda v < (n+1)k- (t-1)\binom{n+1}{\lambda+1}.\]

First note that $nk-(t-1)\binom{n}{\lambda+1} < (n+1)k- (t-1)\binom{n+1}{\lambda+1}$ implies
\begin{equation}\label{E:kBig}
k > (t-1)\binom{n}{\lambda} > (t-1) \binom{n-1}{\lambda}.
\end{equation}
Since \eqref{E:kBig} and $nk-(t-1)\binom{n}{\lambda+1} \leq \lambda v$ hold, there exists a $\mathrm{PD}_\lambda(n;v,k,t)$ by Lemma~\ref{General Construction}.

We will complete the proof by showing that no $\mathrm{PD}_\lambda(n+1;v,k,t)$ exists. By Lemma~\ref{General Upper Bound}, it suffices to show that
\begin{equation}\label{E:SJBspecial}
(t-1)\binom{n+1}{\lambda+1} < v\binom{q}{\lambda+1}+r\binom{q}{\lambda}
\end{equation}
where $q$ and $r$ are the integers such that $(n+1)k=qv+r$ and $0 \leq r < v$. To determine $q$ and $r$, note that $\lambda v < (n+1)k-\binom{n+1}{2}$ implies $\lambda v < (n+1)k$ and hence $q \geq \lambda$. On the other hand, \eqref{E:kBig} yields                  
$(t-1)\binom{n}{\lambda+1}<\frac{n-\lambda}{\lambda+1}k$. Substituting this into $nk-(t-1)\binom{n}{\lambda+1} \leq \lambda v$ and simplifying produces $(n+1)k<(\lambda+1)v$. Hence $q<\lambda+1$. Thus $q=\lambda$ and $r=k(n+1)-\lambda v$, so \eqref{E:SJBspecial} becomes
\[
(t-1)\binom{n+1}{\lambda+1} < k(n+1)-\lambda v,
\]
which is equivalent to our hypothesis that $\lambda v < k(n+1)-(t-1)\binom{n+1}{\lambda+1}$.

\label{T:nBig}
Let $k \geq t \geq 2$ and $\lambda \geq 1$ be integers and let $\ell$ be the least integer such that $(t-1)\binom{\ell}{\lambda} > k$. Then $\mathrm{PDN}_{\lambda}(v,k,t)=\ell$ if
\begin{equation}\label{E:nBigConds}
\ell k-(t-1)\binom{\ell}{\lambda+1} \leq \lambda v < \frac{\lambda+1}{\lambda+2}(\ell+1)k- \frac{t-1}{\lambda+2}\binom{\ell+1}{\lambda+1}.
\end{equation}

We illustrate the inductive step of the proof of Lemma~\ref{lemma:directing} by constructing a $\mathrm{DPD}(4;12,7)$.  The following blocks form a $\mathrm{PD}_2(4;12,7)$ on point set $\{0, \ldots, 11\}$.
\begin{eqnarray*}
B_1&=& \{0,1,2,3,4,5,6\} \\
B_2&=& \{0,1,3,4,7,8,9\} \\
B_3&=& \{0,2,5,6,9,10,11\} \\
B_4&=& \{1,2,7,8,9,10,11\}
\end{eqnarray*}
Removing the point $a=0$, we can order the remaining elements of each block to form the following $\mathrm{DPD}(4;11)$ with block sizes six and seven,
\begin{eqnarray*}
T_1'&=& (1,2,3,4,5,6) \\
T_2'&=& (4,3,7,8,9,1) \\
T_3'&=& (6,5,10,11,9,2) \\
T_4'&=& (2,1,9,11,10,8,7)
\end{eqnarray*}
We have $X=(B_1 \cap B_2) \setminus\{0\}=\{1,3,4\}$, $Y=(B_1 \cap B_3) \setminus\{0\}=\{2,5,6\}$ and $Z=(B_2 \cap B_3) \setminus\{0\}=\{9\}$, where $(x_1,x_2,x_3)=(1,3,4)$, $(y_1,y_2,y_3)=(2,5,6)$ and $(z_1)=(9)$.  It is straightforward to verify that:
\begin{itemize}
\item $j(0)=0$, $j(1)=j(2)=1$, $j(3)=2$, $j(4)=j(5)=j(6)=3$;
\item $k(0)=k(1)=0$, $k(2)=k(3)=k(4)=1$, $k(5)=2$, $k(6)=3$;
\item $R(0)=\{1,2\}$, $R(1)=R(2)=\{0,1,2\}$, $R(3)=R(4)=R(5)=R(6)=\{0,1\}$;
\item $S(0)=S(1)=\{0,1\}$, $S(2)=S(3)=S(4)= \{0,1,2\}$, $S(5)=S(6)=\{1,2\}$.
\end{itemize}
Thus $\ell=1$, and $\{0,1\} \subseteq R(1) \cap S(1)$.  We form $T_1$ by inserting $0$ after the first entry of $T_1'$.   To form $T_2$ from $T_2'$, we insert $0$ so that, in $(z_0,x_4) + T_2' + (x_0,z_2)$, it is between $x_{j(1)+1}=x_2=3$ and $x_{j(1)}=x_1=1$ and also between $z_0$ and $z_1=9$ (i.e.\ $0$ must appear before $9$ in $T_2$).  Similarly, we insert $0$ into $T_3'$ so that, in $(z_2,y_4) + T_2' + (y_0,z_0)$, it is between $y_{k(1)+1}=y_1=2$ and $y_{k(1)}=y_0$ and also between $z_1=9$ and $z_0$.
Also taking $T_4=T_4'$, we obtain a $\mathrm{DPD}(4;12,7)$ with the following blocks.


\begin{eqnarray*}
T_1 &=& (1,0,2,3,4,5,6) \\
T_2 &=& (4,3,7,8,0,9,1) \\
T_3 &=& (6,5,10,11,9,2,0) \\
T_4 &=& (2,1,9,11,10,8,7).
\end{eqnarray*}
